#!/usr/bin/env python3
"""Build the direct-open capability survey from matrix.json."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "papers/capabilities/matrix.json"
OUT = ROOT / "papers/capabilities/index.html"

TEMPLATE = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Arconaut · Capability survey</title>
<style>
:root{color-scheme:light;--ink:#17262c;--muted:#68777b;--line:#d9e1df;--paper:#f4f5f1;--card:#fffefa;--teal:#176c68;--teal-soft:#e0efeb;--rust:#a85335;--navy:#203840;--shadow:0 10px 32px #18353b10}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.5 ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select{font:inherit}button{cursor:pointer;color:inherit}.mast{background:var(--navy);color:#f6f4ea;padding:27px clamp(18px,4vw,58px) 25px}.mast-inner{max-width:1600px;margin:auto}.eyebrow{text-transform:uppercase;letter-spacing:.15em;font-size:10px;color:#a9c9bf;font-weight:750}.mast h1{font:500 clamp(28px,4vw,43px)/1.1 Georgia,serif;letter-spacing:-.025em;margin:8px 0 7px}.mast p{margin:0;color:#cad7d2;max-width:820px}.mast a{color:#c5e9d9}.meta{display:flex;gap:9px;flex-wrap:wrap;margin-top:17px}.chip{border:1px solid #ffffff33;padding:5px 9px;border-radius:99px;color:#d9e7e2;font-size:11px}.wrap{max-width:1600px;margin:auto;padding:21px clamp(12px,2.5vw,36px) 54px}.toolbar{display:grid;grid-template-columns:minmax(210px,1.3fr) repeat(2,minmax(155px,.65fr)) auto;gap:10px;align-items:end;background:var(--card);padding:13px;border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow)}label{display:block;color:var(--muted);font-size:11px;font-weight:700;letter-spacing:.04em;margin:0 0 5px}input,select{width:100%;border:1px solid var(--line);border-radius:7px;background:#fff;padding:9px 10px;color:var(--ink);outline-color:var(--teal)}.toolbar .action{background:var(--teal);border:0;color:white;border-radius:7px;padding:10px 13px;font-weight:700}.counts{margin:15px 2px 10px;color:var(--muted);font-size:12px}.counts strong{color:var(--ink)}.legend{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:13px}.legend button{border:1px solid var(--line);background:#fff;border-radius:6px;padding:5px 8px;font-size:11px;color:var(--muted)}.legend button[aria-pressed="true"]{border-color:var(--teal);background:var(--teal-soft);color:var(--teal)}.legend b{color:var(--ink);margin-right:4px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:14px;align-items:start}.tablebox,.detail{background:var(--card);border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow)}.tablebox{overflow:hidden}.table-scroll{overflow:auto;max-height:72vh}table{border-collapse:separate;border-spacing:0;min-width:100%;white-space:nowrap}th,td{border-bottom:1px solid #e8ece9;padding:0}thead th{position:sticky;top:0;z-index:3;background:#f7f8f4;color:#647276;font-size:10px;letter-spacing:.035em;text-align:center;vertical-align:bottom;height:104px;min-width:38px}thead th:first-child{left:0;z-index:5;text-align:left;min-width:225px;width:225px;padding:10px 12px}thead th:not(:first-child){max-width:44px;padding:5px 2px}thead th button{border:0;background:transparent;color:inherit;padding:0 2px;writing-mode:vertical-rl;transform:rotate(180deg);height:89px;font-size:10px;font-weight:700;white-space:normal;cursor:pointer}thead th button:hover{color:var(--teal)}thead th.active{background:#e3efeb}tbody th{position:sticky;left:0;z-index:2;background:var(--card);text-align:left;padding:9px 12px;min-width:225px;max-width:225px;border-right:1px solid var(--line);font-weight:500}tbody tr{cursor:pointer}tbody tr:hover td,tbody tr:hover th{background:#f4f8f4}tbody tr.selected td,tbody tr.selected th{background:#e7f2ee}tbody th .refname{display:block;font-weight:720;font-size:12px;white-space:normal}.sub{color:var(--muted);font-size:10px;white-space:normal;display:block;margin-top:2px}.cell{display:block;margin:0 auto;width:22px;height:22px;border-radius:6px;text-align:center;line-height:22px;font-weight:800;font-size:11px}.s-I{background:#d9eee4;color:#1f6d50}.s-D{background:#e5e9f7;color:#455a94}.s-L{background:#f7e5d9;color:#9a4c2e}.s-S{background:#eee7d2;color:#77621c}.s-unknown{background:#ecefed;color:#77817e}.s-NA{background:#f0f1ef;color:#a4aaa6}.detail{position:sticky;top:12px;max-height:calc(100vh - 24px);overflow:auto;padding:17px}.detail.empty{color:var(--muted);min-height:190px;display:grid;place-items:center;text-align:center}.detail h2{font:500 24px/1.2 Georgia,serif;margin:1px 0 6px}.detail h3{margin:18px 0 7px;font-size:11px;text-transform:uppercase;letter-spacing:.1em;color:var(--teal)}.detail p{margin:6px 0}.detail .kind{color:var(--muted);font-size:12px}.detail .summary{font-size:13px;line-height:1.55}.detail a{color:var(--teal);overflow-wrap:anywhere}.detail ul{margin:5px 0 0;padding-left:17px}.detail li{margin:5px 0;font-size:12px}.fact{padding:8px 9px;background:#f3f5f1;border-radius:7px;margin:6px 0;font-size:11px}.fact strong{display:block;color:#54666a;font-size:10px;text-transform:uppercase;letter-spacing:.06em;margin-bottom:2px}.cap-row{display:flex;gap:6px;align-items:flex-start;padding:7px 0;border-top:1px solid #ebefec}.cap-row .cell{flex:0 0 22px}.cap-row strong{font-size:12px}.cap-row p{font-size:11px;color:#5d6a6d;margin:2px 0}.tiny{font-size:10px!important;color:var(--muted)}.linkrow{display:flex;gap:12px;flex-wrap:wrap;margin-top:12px;font-size:11px}.notice{font-size:11px;color:var(--muted);padding:10px 12px;border-left:3px solid #c9d9d1;background:#edf2ed;margin:13px 0 0}.emptyrow{padding:30px;text-align:center;color:var(--muted)}
@media(max-width:1050px){.layout{grid-template-columns:1fr}.detail{position:relative;top:auto;max-height:none}.table-scroll{max-height:65vh}}@media(max-width:650px){.toolbar{grid-template-columns:1fr 1fr}.toolbar>div:first-child{grid-column:1/-1}.toolbar .action{grid-column:1/-1}.mast{padding-top:20px}.layout{gap:10px}}
</style>
</head>
<body>
<header class="mast"><div class="mast-inner"><div class="eyebrow">Arconaut · working research</div><h1>Capability survey</h1><p>A comparative map of agent references, their exposed actions, and what the inspected evidence supports. Select a row to read the mechanisms behind its marks.</p><div class="meta"><span class="chip" id="metaRefs">105 references</span><span class="chip" id="metaAxes">23 capability axes</span><span class="chip">Local file · no network required</span></div></div></header>
<main class="wrap"><section class="toolbar" aria-label="Survey filters"><div><label for="q">Search references and inspected details</label><input id="q" type="search" placeholder="Name, summary, actions, evidence…"></div><div><label for="group">Reference group</label><select id="group"><option value="">All groups</option></select></div><div><label for="kind">Role</label><select id="kind"><option value="">All roles</option></select></div><button class="action" id="reset">Reset view</button></section><div class="counts" id="counts"></div><div class="legend" id="legend" aria-label="Capability status filter"></div><div class="layout"><section class="tablebox" aria-label="Capability matrix"><div class="table-scroll"><table><thead id="head"></thead><tbody id="body"></tbody></table></div></section><aside class="detail empty" id="detail"><div>Select a reference to inspect its source notes, actions, evidence, and capability basis.</div></aside></div><p class="notice">Status marks summarize inspected source or documented claims. “I” means implementation traced in source; it does not mean runtime validated. “?” is bounded to the paths inspected and does not claim universal absence.</p></main>
<script id="survey-data" type="application/json">__DATA__</script>
<script>
'use strict';
const data=JSON.parse(document.getElementById('survey-data').textContent);
const statusCode={implemented:'I',documented:'D',limited:'L',mechanism:'S',unknown:'?',na:'NA'};
const labels={I:'Implementation traced',D:'Documented claim',L:'Material limitation',S:'Supporting mechanism', '?':'Not established in inspected paths',NA:'Outside role'};
const escPath=p=>p.split('/').map(encodeURIComponent).join('/');
const capabilities=data.capabilities, refs=data.references;
const q=document.getElementById('q'),group=document.getElementById('group'),kind=document.getElementById('kind'),body=document.getElementById('body'),head=document.getElementById('head'),detail=document.getElementById('detail'),counts=document.getElementById('counts');
let capFocus=new Set(),statusFocus='',selected='',filtered=[];
const uniq=a=>[...new Set(a.filter(Boolean))].sort((x,y)=>x.localeCompare(y));
for(const [sel,vals] of [[group,uniq(refs.map(r=>r.reference.group))],[kind,uniq(refs.map(r=>r.kind))]])for(const v of vals){const o=document.createElement('option');o.value=v;o.textContent=v;sel.append(o)}
const legend=document.getElementById('legend');
for(const [code,meaning] of Object.entries(data.statuses)){const b=document.createElement('button');const c=statusCode[code];b.type='button';b.setAttribute('aria-pressed','false');const mark=node('b','',c);b.append(mark,document.createTextNode(labels[c]));b.title=meaning;b.onclick=()=>{statusFocus=statusFocus===c?'':c;render()};b.dataset.status=c;legend.append(b)}
function capText(c){return c.id.replaceAll('_',' ')}
function renderHead(){head.replaceChildren();const tr=document.createElement('tr');const first=document.createElement('th');first.textContent='Reference · select a row';tr.append(first);for(const c of capabilities){if(capFocus.size&&!capFocus.has(c.id))continue;const th=document.createElement('th');if(capFocus.has(c.id))th.className='active';const b=document.createElement('button');b.type='button';b.textContent=capText(c);b.title=c.meaning+' Click to focus this capability';b.onclick=()=>{capFocus=capFocus.size===1&&capFocus.has(c.id)?new Set():new Set([c.id]);render()};th.append(b);tr.append(th)}head.replaceChildren(tr)}
function allSearch(r){return JSON.stringify(r).toLowerCase()}
function render(){const term=q.value.trim().toLowerCase();filtered=refs.filter(r=>(!group.value||r.reference.group===group.value)&&(!kind.value||r.kind===kind.value)&&(!term||allSearch(r).includes(term))&&(!statusFocus||Object.values(r.capabilities).some(c=>statusCode[c.status]===statusFocus)));renderHead();body.replaceChildren();for(const r of filtered){const tr=document.createElement('tr');if(selected===r.id)tr.className='selected';tr.onclick=()=>{selected=r.id;render();showDetail(r)};const th=document.createElement('th');const nm=document.createElement('span');nm.className='refname';nm.textContent=r.reference.name||r.id;const sb=document.createElement('span');sb.className='sub';sb.textContent=r.reference.group+' · '+r.kind;th.append(nm,sb);tr.append(th);for(const c of capabilities){if(capFocus.size&&!capFocus.has(c.id))continue;const td=document.createElement('td');const cv=r.capabilities[c.id]||{status:'unknown',detail:'No capability entry.'};const code=statusCode[cv.status]||'?';const mark=document.createElement('span');mark.className='cell s-'+(code==='?'?'unknown':code);mark.textContent=code;mark.title=labels[code]+': '+(cv.detail||'');td.append(mark);tr.append(td)}body.append(tr)}if(!filtered.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=1+(capFocus.size?1:capabilities.length);td.className='emptyrow';td.textContent='No references match these filters.';tr.append(td);body.append(tr)}counts.replaceChildren();counts.append(node('strong','',String(filtered.length)),document.createTextNode(' of '+refs.length+' references · showing '),node('strong','',String(capFocus.size||capabilities.length)),document.createTextNode(' of '+capabilities.length+' axes'+(statusFocus?' · status '+statusFocus:'')));for(const b of legend.querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.status===statusFocus));document.getElementById('metaRefs').textContent=refs.length+' references';document.getElementById('metaAxes').textContent=capabilities.length+' capability axes'}
function node(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function list(parent,title,items){if(!items?.length)return;parent.append(node('h3','',title));const ul=node('ul');for(const x of items)ul.append(node('li','',typeof x==='string'?x:JSON.stringify(x)));parent.append(ul)}
function showDetail(r){detail.className='detail';detail.replaceChildren();detail.append(node('h2','',r.reference.name||r.id),node('div','kind',r.kind+' · '+r.reference.group),node('p','summary',r.summary||''));const meta=node('div');for(const [k,v] of [['Runtime',r.runtime?.languages?.join(', ')],['Execution',r.runtime?.execution],['Service boundary',r.runtime?.service_boundary],['Revision',r.reference.revision||r.reference.version],['Source',r.reference.source]])if(v){const f=node('div','fact');f.append(node('strong','',k),node('span','',v));meta.append(f)}detail.append(meta);list(detail,'Actions and lifecycle',r.actions?.map(a=>`${a.name} · ${a.surface}\nInput: ${a.input}\nOutput: ${a.output}\nLifecycle: ${a.lifecycle}\nAuthority: ${a.authority}`));detail.append(node('h3','','Capability detail'));for(const c of capabilities){const v=r.capabilities[c.id]||{};if(!capFocus.size||capFocus.has(c.id)){const row=node('div','cap-row');const code=statusCode[v.status]||'?';row.append(node('span','cell s-'+(code==='?'?'unknown':code),code));const text=node('div');text.append(node('strong','',capText(c)+' — '+labels[code]),node('p','',v.detail||'No detail recorded.'));if(v.basis)text.append(node('p','tiny','Basis: '+v.basis));if(v.evidence?.length)text.append(node('p','tiny','Evidence: '+v.evidence.join(', ')));row.append(text);detail.append(row)}}list(detail,'Strengths',r.strengths);list(detail,'Limits and inspection scope',[...(r.limits||[]),...(r.inspection?.limits?[r.inspection.limits]:[])]);list(detail,'Questions for Arconaut',r.arconaut_questions);list(detail,'Source evidence',r.evidence?.map(e=>`${e.id} · ${e.claim} — ${e.path}${e.start?':'+e.start+(e.end&&e.end!==e.start?'-'+e.end:''):''}`));list(detail,'Tests read (not run)',r.tests?.map(t=>`${t.focus}: ${t.oracle} (${t.path}; executed: ${t.executed})`));const links=node('div','linkrow');const d=document.createElement('a');d.href='dossiers/'+encodeURIComponent(r.id)+'.md';d.textContent='Open dossier';d.target='_blank';links.append(d);const src=document.createElement('a');src.href='../../'+escPath(r.reference.destination||'');src.textContent='Reference directory';src.target='_blank';links.append(src);detail.append(links)}
q.addEventListener('input',render);group.addEventListener('change',render);kind.addEventListener('change',render);document.getElementById('reset').onclick=()=>{q.value='';group.value='';kind.value='';statusFocus='';capFocus=new Set();selected='';render();detail.className='detail empty';detail.replaceChildren(node('div','','Select a reference to inspect its source notes, actions, evidence, and capability basis.'))};render();
</script>
</body>
</html>
'''


def main() -> None:
    payload = json.dumps(json.loads(DATA.read_text()), ensure_ascii=False, separators=(",", ":"))
    # The JSON is embedded as inert application/json; escape HTML-significant chars
    # so strings from source material cannot close the script element.
    payload = payload.replace("&", "\\u0026").replace("<", "\\u003c").replace(">", "\\u003e")
    OUT.write_text(TEMPLATE.replace("__DATA__", payload))
    print(f"Wrote {OUT.relative_to(ROOT)} ({len(json.loads(payload)['references'])} references)")


if __name__ == "__main__":
    main()
